action.command:
cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger/swagger-ui-init.js");
  const txt = await r.text();
  // balanced-brace extraction of swaggerDoc value
  const start = txt.indexOf("\"swaggerDoc\"") + "\"swaggerDoc\"".length;
  const braceStart = txt.indexOf("{", start);
  let depth = 0, i = braceStart, inStr = false, esc = false;
  for (; i < txt.length; i++) {
    const c = txt[i];
    if (inStr) { if (esc) esc = false; else if (c === "\\\\") esc = true; else if (c === "\"") inStr = false; }
    else if (c === "\"") inStr = true;
    else if (c === "{") depth++;
    else if (c === "}") { depth--; if (depth === 0) break; }
  }
  const spec = JSON.parse(txt.slice(braceStart, i + 1));
  const sch = spec.paths["/auth/init-email-login"].post.requestBody.content["application/json"].schema;
  console.log("INIT schema:", JSON.stringify(sch));
  const names = [];
  (function walk(s){ if(!s||typeof s!=="object")return; if(s.$ref) names.push(s.$ref.replace("#/components/schemas/","")); for(const v of Object.values(s)) walk(v); })(sch);
  console.log("refs:", names);
  for (const n of names) { const s = spec.components.schemas[n]; if(s) console.log("---", n, ":", JSON.stringify(s).slice(0,800)); }
  const comp = spec.paths["/auth/complete-email-login"].post.requestBody.content["application/json"].schema;
  console.log("COMPLETE schema:", JSON.stringify(comp));
})();
' 2>&1 | head -40

